<?php
declare(strict_types=1);
namespace FMonitor2\DeadlineTransferCertificate;

use FMonitor2\AssignmentOrderOriginal\{FMonitorPassivePdfInspector,AssignmentOrderOriginalPdfStatus};

/** Public application facade and sole MariaDB state owner for deadline certificates. */
class MariaDbDeadlineTransferCertificates
{
 public function __construct(private \mysqli$db,private string$p,private $clock,private $observer=null){if(preg_match('/^[A-Za-z0-9_]{0,25}$/D',$p)!==1)throw new \InvalidArgumentException();}
 public function submit(array$c,callable$stream):array
 {
  $this->command($c);$this->authorize($c['actorId'],'deadline_certificate.write');$this->case($c['installationCaseId']);$bytes=$this->bytes($stream);$this->pdf($bytes);
  $semantic=[];foreach(['requestId','installationCaseId','actorId','expectedVersion','certificateDate','newDeadline','correctionReason','sourceLabel','sourceLocator','mediaType']as$key)$semantic[$key]=$c[$key];
  $semantic['pdfSha256']=hash('sha256',$bytes);$requestHash=hash('sha256',json_encode($semantic,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));
  if($prior=$this->operation($c['actorId'],$c['requestId'])){if(!hash_equals($prior['request_sha256'],$requestHash))throw new \DomainException('OPERATION_CONFLICT');return['status'=>'replayed','revision'=>$this->revision((int)$prior['revision_id'])];}
  if($this->db->query('SELECT @@in_transaction')->fetch_column())throw new \LogicException('Caller transaction not supported');
  try{
   $this->db->begin_transaction();$caseLock=$this->db->prepare("SELECT id FROM `{$this->p}fm2_installation_cases` WHERE id=? FOR UPDATE");$caseLock->execute([$c['installationCaseId']]);$caseLock->get_result()->fetch_assoc();$root=$this->root($c['installationCaseId'],true);$version=$root?(int)$root['current_version']:0;
   if($version!==$c['expectedVersion'])throw new \DomainException('STALE_REVISION');
   if($version===0&&$c['correctionReason']!==null||$version>0&&$c['correctionReason']===null)throw new \DomainException('INVALID_COMMAND');
   $previous=$root?(int)$root['current_revision_id']:null;$at=($this->clock)();$sha=hash('sha256',$bytes);$size=strlen($bytes);
   $q=$this->db->prepare("INSERT INTO `{$this->p}fm2_deadline_certificate_revisions`(installation_case_id,revision_number,previous_revision_id,certificate_date,new_deadline,correction_reason,actor_id,recorded_at,source_label,source_locator,pdf_sha256,byte_size)VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");
   $q->execute([$c['installationCaseId'],$version+1,$previous,$c['certificateDate'],$c['newDeadline'],$c['correctionReason'],$c['actorId'],$at,$c['sourceLabel'],$c['sourceLocator'],$sha,$size]);$id=$this->db->insert_id;
   if($root){$q=$this->db->prepare("UPDATE `{$this->p}fm2_deadline_certificate_roots` SET current_revision_id=?,current_version=? WHERE installation_case_id=? AND current_version=?");$q->execute([$id,$version+1,$c['installationCaseId'],$version]);if($q->affected_rows!==1)throw new \DomainException('STALE_REVISION');}
   else{$q=$this->db->prepare("INSERT INTO `{$this->p}fm2_deadline_certificate_roots` VALUES(?,?,?)");$q->execute([$c['installationCaseId'],$id,1]);}
   $q=$this->db->prepare("INSERT INTO `{$this->p}fm2_deadline_certificate_operations` VALUES(?,?,?,?)");$q->execute([$c['actorId'],$c['requestId'],$requestHash,$id]);
   for($n=0,$off=0;$off<$size;$n++,$off+=65536){$chunk=substr($bytes,$off,65536);$q=$this->db->prepare("INSERT INTO `{$this->p}fm2_deadline_certificate_pdf_chunks` VALUES(?,?,?)");$q->bind_param('iis',$id,$n,$chunk);$q->execute();}
   if($this->observer)($this->observer)('beforeCommit');$this->db->commit();$revision=$this->revision($id);
   if($this->observer)try{($this->observer)('afterCommit');}catch(\Throwable){throw new \DomainException('OUTCOME_UNKNOWN');}
   return['status'=>'accepted','revision'=>$revision];
  }catch(\DomainException$e){if($e->getMessage()!=='OUTCOME_UNKNOWN')try{$this->db->rollback();}catch(\Throwable){}throw$e;}
  catch(\Throwable$e){try{$this->db->rollback();}catch(\Throwable){throw new \DomainException('OUTCOME_UNKNOWN');}throw new \DomainException('STORAGE_UNAVAILABLE');}
 }
 public function read(int$actor,int$case):array{$this->authorize($actor,'deadline_certificate.read');$this->case($case);$root=$this->root($case,false);if(!$root)return['current'=>null,'history'=>[]];$rows=$this->db->query("SELECT * FROM `{$this->p}fm2_deadline_certificate_revisions` WHERE installation_case_id=$case ORDER BY revision_number")->fetch_all(MYSQLI_ASSOC);$history=array_map(fn($r)=>$this->map($r),$rows);$this->chain($root,$history);return['current'=>$history[array_key_last($history)],'history'=>$history];}
 public function download(int$actor,int$revision):array{$this->authorize($actor,'deadline_certificate.read');$r=$this->revision($revision);$root=$this->root($r["installationCaseId"],false);if(!$root)throw new \DomainException("CERTIFICATE_EVIDENCE_INVALID");$this->chain($root,$this->readEvidence($r["installationCaseId"]));$bytes='';$q=$this->db->prepare("SELECT chunk_no,bytes FROM `{$this->p}fm2_deadline_certificate_pdf_chunks` WHERE revision_id=? ORDER BY chunk_no");$q->execute([$revision]);$i=0;foreach($q->get_result()->fetch_all(MYSQLI_ASSOC)as$x){if((int)$x['chunk_no']!==$i++)throw new \DomainException('CERTIFICATE_EVIDENCE_INVALID');$bytes.=$x['bytes'];}if(strlen($bytes)!==$r['byteSize']||!hash_equals($r['pdfSha256'],hash('sha256',$bytes))||!$this->date($r['certificateDate'])||!$this->date($r['newDeadline']))throw new \DomainException('CERTIFICATE_EVIDENCE_INVALID');return['bytes'=>$bytes,'mediaType'=>'application/pdf','byteSize'=>$r['byteSize'],'pdfSha256'=>$r['pdfSha256'],'filename'=>'deadline-certificate-'.$revision.'.pdf'];}
 public function currentEvidence(int$case):?array{$root=$this->root($case,false);if(!$root)return null;$history=$this->readEvidence($case);$this->chain($root,$history);$r=$history[array_key_last($history)];return array_merge($r,['source'=>['label'=>$r['sourceLabel'],'locator'=>'fm2_deadline_certificate_revisions/'.$r['id'],'contentSha256'=>hash('sha256',json_encode($r,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))]]);}
 private function readEvidence(int$c):array{$rows=$this->db->query("SELECT * FROM `{$this->p}fm2_deadline_certificate_revisions` WHERE installation_case_id=$c ORDER BY revision_number")->fetch_all(MYSQLI_ASSOC);return array_map(fn($r)=>$this->map($r),$rows);}
 private function chain(array$root,array$h):void{if(count($h)!==(int)$root['current_version']||$h===[]||(int)$root['current_revision_id']!==$h[array_key_last($h)]['id'])throw new \DomainException('CERTIFICATE_EVIDENCE_INVALID');foreach($h as$i=>$r){if(!$this->validStoredBytes($r)||$r['revisionNumber']!==$i+1||$r['previousRevisionId']!==($i?$h[$i-1]['id']:null)||!$this->date($r['certificateDate'])||!$this->date($r['newDeadline']))throw new \DomainException('CERTIFICATE_EVIDENCE_INVALID');}}
 private function validStoredBytes(array$r):bool{$q=$this->db->prepare("SELECT chunk_no,bytes FROM `{$this->p}fm2_deadline_certificate_pdf_chunks` WHERE revision_id=? ORDER BY chunk_no");$q->execute([$r['id']]);$bytes='';$i=0;foreach($q->get_result()->fetch_all(MYSQLI_ASSOC)as$x){if((int)$x['chunk_no']!==$i++)return false;$bytes.=$x['bytes'];}return strlen($bytes)===$r['byteSize']&&hash_equals($r['pdfSha256'],hash('sha256',$bytes));}
 private function command(array$c):void{$keys=['requestId','installationCaseId','actorId','expectedVersion','certificateDate','newDeadline','correctionReason','sourceLabel','sourceLocator','mediaType'];foreach($keys as$k)if(!array_key_exists($k,$c))throw new \DomainException('INVALID_COMMAND');$text=fn($v,$max)=>is_string($v)&&$v!==''&&trim($v)===$v&&mb_strlen($v)<= $max;if(!is_int($c['installationCaseId'])||$c['installationCaseId']<1||!is_int($c['actorId'])||$c['actorId']<1||!is_int($c['expectedVersion'])||$c['expectedVersion']<0||(($c['expectedVersion']===0)!==($c['correctionReason']===null))||!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/D',$c['requestId'])||!$this->date($c['certificateDate'])||!$this->date($c['newDeadline'])||!$text($c['sourceLabel'],500)||!$text($c['sourceLocator'],500)||$c['mediaType']!=='application/pdf'||($c['correctionReason']!==null&&!$text($c['correctionReason'],1000)))throw new \DomainException('INVALID_COMMAND');}
 private function date(mixed$v):bool{if(!is_string($v)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v))return false;$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);return$d&&$d->format('Y-m-d')===$v;}
 private function bytes(callable$s):string{$b='';try{while(($x=$s())!==null){if(!is_string($x)||$x===''||strlen($x)>65536)throw new \RuntimeException();$b.=$x;if(strlen($b)>20971520)throw new \LengthException();}}catch(\LengthException){throw new \DomainException('INVALID_PDF');}catch(\Throwable){throw new \DomainException('STORAGE_UNAVAILABLE');}if($b==='')throw new \DomainException('INVALID_PDF');return$b;}
 private function pdf(string$b):void{$x=(new FMonitorPassivePdfInspector())->inspect($b);if($x->status!==AssignmentOrderOriginalPdfStatus::PASSIVE_PDF)throw new \DomainException('INVALID_PDF');}
 private function authorize(int$a,string$cap):void{$q=$this->db->prepare("SELECT 1 FROM `{$this->p}fm2_pilot_users`u JOIN `{$this->p}fm2_pilot_user_roles`ur ON ur.user_id=u.user_id JOIN `{$this->p}fm2_pilot_roles`r ON r.role_id=ur.role_id JOIN `{$this->p}fm2_pilot_role_permissions`rp ON rp.role_id=r.role_id WHERE u.user_id=? AND u.status=1 AND u.activation_state='active' AND r.status=1 AND BINARY rp.permission=? LIMIT 1");$q->execute([$a,$cap]);if(!$q->get_result()->fetch_column())throw new \DomainException('FORBIDDEN');}
 private function case(int$c):void{$q=$this->db->prepare("SELECT 1 FROM `{$this->p}fm2_installation_cases` WHERE id=?");$q->execute([$c]);if(!$q->get_result()->fetch_column())throw new \DomainException('CASE_NOT_FOUND');}
 private function root(int$c,bool$lock):?array{$q=$this->db->prepare("SELECT * FROM `{$this->p}fm2_deadline_certificate_roots` WHERE installation_case_id=?".($lock?' FOR UPDATE':''));$q->execute([$c]);return$q->get_result()->fetch_assoc()?:null;}
 private function operation(int$a,string$r):?array{$q=$this->db->prepare("SELECT * FROM `{$this->p}fm2_deadline_certificate_operations` WHERE actor_id=? AND request_id=?");$q->execute([$a,$r]);return$q->get_result()->fetch_assoc()?:null;}
 private function revision(int$id):array{$q=$this->db->prepare("SELECT * FROM `{$this->p}fm2_deadline_certificate_revisions` WHERE id=?");$q->execute([$id]);$r=$q->get_result()->fetch_assoc();if(!$r)throw new \DomainException('CASE_NOT_FOUND');return$this->map($r);}
 private function map(array$r):array{return['id'=>(int)$r['id'],'installationCaseId'=>(int)$r['installation_case_id'],'revisionNumber'=>(int)$r['revision_number'],'previousRevisionId'=>$r['previous_revision_id']===null?null:(int)$r['previous_revision_id'],'certificateDate'=>$r['certificate_date'],'newDeadline'=>$r['new_deadline'],'correctionReason'=>$r['correction_reason'],'actorId'=>(int)$r['actor_id'],'recordedAt'=>$r['recorded_at'],'sourceLabel'=>$r['source_label'],'sourceLocator'=>$r['source_locator'],'pdfSha256'=>$r['pdf_sha256'],'byteSize'=>(int)$r['byte_size']];}
}
